#include <bits/stdc++.h>
using namespace std;
// #define long long ll
int main() {
	// your code goes here
    int t;
    cin >> t;
    while(t--){
        int n;
        cin >> n;
        int m = 3*n;
        
        vector<long long> a(m);
        for(auto &i: a) cin >> i;
        sort(a.rbegin(), a.rend());
        
        vector<long long> prefix(m+1, 0);
        
        for (int i =0; i<m; i++){
            prefix[i+1] = prefix[i]+a[i];
        }
        
        long long ans = 0;
        
        for (int i=0; i<=n; i++){
            auto temp = [&](int j)-> long long{
                int x = i + 2 * j;
                int y = 3*n - 2 * i - j;
                return 2*prefix[i]+prefix[x]+3*prefix[y];
            };
            
            int low = 0; int high = n-i;
            
            while (low < high){
                int mid = (low + high) / 2;
                if (temp(mid+1) > temp(mid)){
                    low  = mid +1;
                }else{
                    high = mid;
                }
            }
            ans = max(ans, temp(low));
        }
        
        cout << ans << "\n";
    }
}
